#define k_button_endless_game_y						( GAME_SCREEN_H2 + 40 )
#define k_button_endless_game_w						( m_sprite->GetFrameWidth ( k_button_endless_frame ) )
#define k_button_endless_game_h						( m_sprite->GetFrameHeight( k_button_endless_frame ) )
