#define k_button_endless_game_anim_pressed			( MENU_A_MENU_BASE_BUTTON_PRESSED )
#define k_button_endless_game_anim_blink			( MENU_A_MENU_BASE_BUTTON_BLINK )
#define	k_button_endless_text						( STRING_IDS::MENU_NEW_GAME_ENDLESS )
#define	k_button_endless_font1						( "MM_Normal" )
